-- Permission vocabulary and system roles of the performance module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the performance permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('appraisal:create'::text, 'appraisal'::text, 'create'::text, 'Create appraisal'::text),
            ('appraisal:delete'::text, 'appraisal'::text, 'delete'::text, 'Delete appraisal'::text),
            ('appraisal:purge'::text, 'appraisal'::text, 'purge'::text, 'Purge appraisal'::text),
            ('appraisal:read'::text, 'appraisal'::text, 'read'::text, 'Read appraisal'::text),
            ('appraisal:restore'::text, 'appraisal'::text, 'restore'::text, 'Restore appraisal'::text),
            ('appraisal:update'::text, 'appraisal'::text, 'update'::text, 'Update appraisal'::text),
            ('appraisal_cycle:create'::text, 'appraisal_cycle'::text, 'create'::text, 'Create appraisal cycle'::text),
            ('appraisal_cycle:delete'::text, 'appraisal_cycle'::text, 'delete'::text, 'Delete appraisal cycle'::text),
            ('appraisal_cycle:purge'::text, 'appraisal_cycle'::text, 'purge'::text, 'Purge appraisal cycle'::text),
