            ('appraisal_cycle:restore'::text, 'appraisal_cycle'::text, 'restore'::text, 'Restore appraisal cycle'::text),
            ('appraisal_cycle:update'::text, 'appraisal_cycle'::text, 'update'::text, 'Update appraisal cycle'::text),
            ('feedback:create'::text, 'feedback'::text, 'create'::text, 'Create feedback'::text),
            ('feedback:delete'::text, 'feedback'::text, 'delete'::text, 'Delete feedback'::text),
            ('feedback:purge'::text, 'feedback'::text, 'purge'::text, 'Purge feedback'::text),
            ('feedback:read'::text, 'feedback'::text, 'read'::text, 'Read feedback'::text),
            ('feedback:restore'::text, 'feedback'::text, 'restore'::text, 'Restore feedback'::text),
            ('feedback:update'::text, 'feedback'::text, 'update'::text, 'Update feedback'::text),
            ('goal:create'::text, 'goal'::text, 'create'::text, 'Create goal'::text),
            ('goal:delete'::text, 'goal'::text, 'delete'::text, 'Delete goal'::text),
            ('goal:purge'::text, 'goal'::text, 'purge'::text, 'Purge goal'::text),
            ('goal:read'::text, 'goal'::text, 'read'::text, 'Read goal'::text),
            ('goal:restore'::text, 'goal'::text, 'restore'::text, 'Restore goal'::text),
            ('goal:update'::text, 'goal'::text, 'update'::text, 'Update goal'::text),
            ('reward:create'::text, 'reward'::text, 'create'::text, 'Create reward'::text),
            ('reward:delete'::text, 'reward'::text, 'delete'::text, 'Delete reward'::text),
            ('reward:purge'::text, 'reward'::text, 'purge'::text, 'Purge reward'::text),
            ('reward:read'::text, 'reward'::text, 'read'::text, 'Read reward'::text),
            ('reward:restore'::text, 'reward'::text, 'restore'::text, 'Restore reward'::text),
            ('reward:update'::text, 'reward'::text, 'update'::text, 'Update reward'::text),
            ('talent_matrix_entry:create'::text, 'talent_matrix_entry'::text, 'create'::text, 'Create talent matrix entry'::text),
            ('talent_matrix_entry:delete'::text, 'talent_matrix_entry'::text, 'delete'::text, 'Delete talent matrix entry'::text),
            ('talent_matrix_entry:purge'::text, 'talent_matrix_entry'::text, 'purge'::text, 'Purge talent matrix entry'::text),
            ('talent_matrix_entry:read'::text, 'talent_matrix_entry'::text, 'read'::text, 'Read talent matrix entry'::text),
            ('talent_matrix_entry:restore'::text, 'talent_matrix_entry'::text, 'restore'::text, 'Restore talent matrix entry'::text),
            ('talent_matrix_entry:update'::text, 'talent_matrix_entry'::text, 'update'::text, 'Update talent matrix entry'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('appraisal:create'::text, 'appraisal'::text, 'create'::text, 'Create appraisal'::text),
            ('appraisal:delete'::text, 'appraisal'::text, 'delete'::text, 'Delete appraisal'::text),
            ('appraisal:purge'::text, 'appraisal'::text, 'purge'::text, 'Purge appraisal'::text),
            ('appraisal:read'::text, 'appraisal'::text, 'read'::text, 'Read appraisal'::text),
            ('appraisal:restore'::text, 'appraisal'::text, 'restore'::text, 'Restore appraisal'::text),
